INSERT INTO users (user_id, user_name, user_passwd, user_email, approved)
INSERT INTO roles (user_id, user_role) SELECT u.user_id, 'ADMIN' FROM users u WHERE u.user_email = 'admin@gmail.com' AND NOT EXISTS (SELECT 1 FROM roles r WHERE r.user_id=u.user_id AND r.user_role='ADMIN');
INSERT INTO roles (user_id, user_role) SELECT u.user_id, 'USER' FROM users u WHERE u.user_email = 'admin@gmail.com' AND NOT EXISTS (SELECT 1 FROM roles r WHERE r.user_id=u.user_id AND r.user_role='USER');
